class Solution {
public:
    string smallestNumber(string pattern) {
        int n = pattern.size();
        string result(n + 1, ' ');
        for (int i = 0; i <= n; i++) {
            result[i] = '1' + i;
        }

        int i = 0;
        while (i < n) {
            if (pattern[i] == 'D') {
                int start = i;
                while (i < n && pattern[i] == 'D') {
                    i++;
                }
                reverse(result.begin() + start, result.begin() + i + 1);
            } else {
                i++;
            }
        }

        return result;
    }
};
